# 3-chunk variants
for cut in range(1, len(raw)-1):
    out = run([raw[:cut], raw[cut:cut+3], raw[cut+3:]])
    if token in out:
        print("3chunk leak at", cut, repr(out)); break
else:
    print("3chunk: clean")
